export const createQuotationTemplateBodyNameMin = 2;
export const createQuotationTemplateBodyNameMax = 100;

export const createQuotationTemplateBodyDescriptionOneMax = 500;

export const createQuotationTemplateBodyItemsItemSpaceNameOneMax = 100;

export const createQuotationTemplateBodyItemsItemProductIdRegExp = new RegExp('^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$');
export const createQuotationTemplateBodyItemsItemQtyOneMin = 0;

export const createQuotationTemplateBodyItemsItemQtyTwoRegExp = new RegExp('^\\d+(\\.\\d{1,3})?$');



export const CreateQuotationTemplateBody = zod.object({
  "name": zod.string().min(createQuotationTemplateBodyNameMin).max(createQuotationTemplateBodyNameMax),
  "description": zod.union([zod.string().max(createQuotationTemplateBodyDescriptionOneMax),zod.null()]).optional(),
  "type": zod.enum(['PRODUCT', 'SITE_DIVISION']),
  "items": zod.array(zod.object({
  "spaceName": zod.union([zod.string().max(createQuotationTemplateBodyItemsItemSpaceNameOneMax),zod.null()]).optional(),
  "productId": zod.uuid().regex(createQuotationTemplateBodyItemsItemProductIdRegExp),
  "qty": zod.union([zod.number().min(createQuotationTemplateBodyItemsItemQtyOneMin),zod.string().regex(createQuotationTemplateBodyItemsItemQtyTwoRegExp)])
})).min(1)
})

